import importlib.util,json,statistics
from pathlib import Path
w=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('diag','/Users/0x1/Documents/htdocs/altbak.pub-gopurs/bin/benchmark/json-diagnostic.py');d=importlib.util.module_from_spec(spec);spec.loader.exec_module(d)
o=w/'ablation';o.mkdir(exist_ok=False)
corpus,_=d.corpus_data('JsonDecoding');(o/'corpus.json').write_bytes(corpus)
e=d.environment();e['DIAG_CORPUS']=str(o/'corpus.json')
bins={'full':w/'after/JsonDecoding/benchmark','without':w/'without-sum/benchmark','value-only':w/'sum-value-only/benchmark'}
hashes={k:d.sha(b) for k,b in bins.items()}
r={k:[] for k in bins};oracle=json.loads((d.fixtures('JsonDecoding')/'expected.json').read_text())
order=['full','without','value-only','value-only','without','full','without','full','value-only']
for i,k in enumerate(order):
 log=o/f'{i}-{k}.json';d.call([bins[k]],bins[k].parent,log,e)
 data=json.loads(log.read_text());d.validate_result(data,oracle,'JsonDecoding');r[k].append(data)
 print(k,{p:round(v['time_us']/1000,3) for p,v in data['phases'].items()},flush=True)
m={k:{p:statistics.median(x['phases'][p]['time_us'] for x in runs) for p in ['parse','decode','combined']} for k,runs in r.items()}
a={k:{p:statistics.median(s['allocated_bytes'] for x in runs for s in x['phases'][p]['samples']) for p in ['parse','decode','combined']} for k,runs in r.items()}
assert hashes=={k:d.sha(b) for k,b in bins.items()}
report={'medians_us':m,'allocated_bytes':a,'results':r,'order':order,'binary_sha256':hashes}
(o/'results.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'medians_us':m,'allocated_bytes':a},indent=2))
(o/'corpus.json').unlink()

